define(["core/notification","mod_videoannotation/player"],function(Notification,Player){const init=()=>{document.querySelectorAll('[data-region="videoannotation-report"]').forEach(root=>{let config;try{config=JSON.parse(root.dataset.config||"{}")}catch(error){Notification.exception(error);return}Player.create(root,config.player).then(player=>{root.querySelectorAll('[data-action="seek"]').forEach(button=>{button.addEventListener("click",()=>{player.seek(Number(button.dataset.time||0));root.querySelector('[data-region="player-container"]')?.scrollIntoView({behavior:"smooth",block:"center"})})})}).catch(error=>Notification.exception(error))})};return{init:init}});